            cnt_10 <= cnt_10 + 1;
        end

        // Counter for 1MHz output
        if (cnt_1 == 7'b1111111) begin
            CLK_1 <= ~CLK_1;
            cnt_1 <= 7'b0000000;
        end else begin
            cnt_1 <= cnt_1 + 1;
        end
    end
end

endmodule

module freq_divbyodd #(
    parameter NUM_DIV = 5 // Default divisor is 5, must be an odd number
) (
    input wire clk,        // Input clock signal
    input wire rst_n,      // Active low reset signal
    output reg clk_div     // Divided clock output
);

// Internal signals for counters and dividers
reg [NUM_DIV-2:0] cnt1;  // Counter for rising edge divider
reg [NUM_DIV-2:0] cnt2;  // Counter for falling edge divider
reg clk_div1;            // Clock divider for positive edges
reg clk_div2;            // Clock divider for negative edges

// Always block to handle the logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset counters and dividers
        cnt1 <= 0;
        cnt2 <= 0;
        clk_div1 <= 0;
        clk_div2 <= 0;
        clk_div <= 0;
    end else begin
        // Rising edge divider logic
        if (cnt1 == NUM_DIV/2 - 1) begin
            clk_div1 <= ~clk_div1;  // Toggle the positive edge divider
            cnt1 <= 0;              // Reset counter for next cycle
        end else begin
            cnt1 <= cnt1 + 1;       // Increment counter
        end

        // Falling edge divider logic
        if (cnt2 == NUM_DIV/2 - 1) begin
            clk_div2 <= ~clk_div2;  // Toggle the negative edge divider
            cnt2 <= 0;              // Reset counter for next cycle
        end else begin
            cnt2 <= cnt2 + 1;       // Increment counter
        end

        // Final divided clock output
        clk_div <= clk_div1 | clk_div2;
    end
end

endmodule
